"use client";

import { useEffect, useMemo, useState } from "react";
import Image from "next/image";
import { Search, ShoppingBag, X, Download, Loader2 } from "lucide-react";

type BookItem = {
  id: string;
  title: string;
  author: string | null;
  tagline: string | null;
  description: string | null;
  learning: string | null;
  note: string | null;
  imageUrl: string | null;
  buyUrl: string | null;
  free: boolean;
};

type Variant = "published" | "read" | "ebook";

type DownloadTarget = {
  id: string;
  title: string;
};

export function BookLibrary({ books, variant }: { books: BookItem[]; variant: Variant }) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState<BookItem | null>(null);
  const [target, setTarget] = useState<DownloadTarget | null>(null);

  // Download form state
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [optInNewsletter, setOptInNewsletter] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return books;
    return books.filter((b) =>
      [b.title, b.author, b.tagline, b.description, b.learning, b.note]
        .filter(Boolean)
        .some((t) => t!.toLowerCase().includes(q))
    );
  }, [books, query]);

  useEffect(() => {
    if (!active && !target) return;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && (setActive(null), setTarget(null));
    window.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = "";
      window.removeEventListener("keydown", onKey);
    };
  }, [active, target]);

  const isFreeEbook = (b: BookItem) => variant === "ebook" && b.free;

  const ctaLabel = (b: BookItem) =>
    variant === "published" ? "Get your Copy" : variant === "ebook" ? (b.free ? "Download" : "Buy Now") : "Buy this Book";

  const openDownload = (b: BookItem) => {
    setTarget({ id: b.id, title: b.title });
    setActive(null);
    setError(null);
  };

  const resetForm = () => {
    setTarget(null);
    setName("");
    setEmail("");
    setAcceptedTerms(false);
    setOptInNewsletter(false);
    setError(null);
    setSubmitting(false);
  };

  const submitDownload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!target) return;
    setError(null);
    setSubmitting(true);
    try {
      const res = await fetch(`/api/ebooks/download/${target.id}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, acceptedTerms, newsletter: optInNewsletter }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setError(data?.error ?? "Something went wrong. Please try again.");
        setSubmitting(false);
        return;
      }
      const blob = await res.blob();
      const disposition = res.headers.get("Content-Disposition") ?? "";
      const match = disposition.match(/filename="([^"]+)"/);
      const fileName = match?.[1] ?? `${target.title.replace(/\s+/g, "-")}.pdf`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      resetForm();
    } catch {
      setError("Something went wrong. Please try again.");
      setSubmitting(false);
    }
  };

  return (
    <>
      {/* Search */}
      <label className="relative mx-auto mb-10 block max-w-md">
        <span className="sr-only">Search books</span>
        <Search className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <input
          type="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder={variant === "ebook" ? "Search eBooks…" : "Search books…"}
          className="w-full rounded-full border border-border bg-background py-3 pl-11 pr-4 text-sm outline-none transition-colors focus:border-accent"
        />
      </label>

      {filtered.length === 0 ? (
        <p className="text-center text-muted-foreground">No results for &ldquo;{query}&rdquo;.</p>
      ) : (
        <div className="grid grid-cols-1 gap-x-6 gap-y-12 sm:grid-cols-2 lg:mx-auto lg:max-w-4xl">
          {filtered.map((book) => (
            <article key={book.id} className="group flex flex-col text-center">
              <button
                type="button"
                onClick={() => setActive(book)}
                aria-label={`View details for ${book.title}`}
                className="relative mx-auto aspect-[3/4] w-full max-w-[260px] text-left focus-visible:outline-none"
              >
                {book.imageUrl ? (
                  <Image
                    src={book.imageUrl}
                    alt={book.title}
                    fill
                    sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 400px"
                    className="object-contain drop-shadow-xl transition-transform duration-500 group-hover:-translate-y-1.5"
                  />
                ) : (
                  <div className="grid h-full w-full place-items-center rounded-3xl bg-muted p-6">
                    <span className="font-display font-bold text-muted-foreground">{book.title}</span>
                  </div>
                )}
              </button>

              <button
                type="button"
                onClick={() => setActive(book)}
                className="mt-5 focus-visible:outline-none"
              >
                {book.tagline || book.author ? (
                  <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-accent-strong">
                    {variant === "read" ? book.author : book.tagline}
                  </p>
                ) : null}
                <h3 className="font-display text-lg font-bold leading-snug transition-colors group-hover:text-accent-strong">
                  {book.title}
                </h3>
              </button>

              {(book.description || book.learning) && (
                <p className="mx-auto mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground line-clamp-2">
                  {variant === "read" ? book.learning : book.description}
                </p>
              )}

              {isFreeEbook(book) ? (
                <button
                  type="button"
                  onClick={() => openDownload(book)}
                  className="mt-5 inline-flex items-center justify-center gap-2 self-center rounded-full bg-accent px-6 py-2.5 text-sm font-semibold text-accent-foreground shadow-sm transition-opacity hover:opacity-90"
                >
                  <Download className="h-4 w-4" />
                  Download
                </button>
              ) : variant === "read" ? null : (
                <a
                  href={book.buyUrl ?? "#"}
                  data-no-modal
                  onClick={(e) => !book.buyUrl && e.preventDefault()}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-5 inline-flex items-center justify-center gap-2 self-center rounded-full bg-accent px-6 py-2.5 text-sm font-semibold text-accent-foreground shadow-sm transition-opacity hover:opacity-90"
                >
                  <ShoppingBag className="h-4 w-4" />
                  {ctaLabel(book)}
                </a>
              )}
            </article>
          ))}
        </div>
      )}

      {/* Detail modal */}
      {active && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-black/50 backdrop-blur-sm"
            onClick={() => setActive(null)}
          />
          <div
            role="dialog"
            aria-modal="true"
            aria-label={active.title}
            className="relative grid w-full max-w-3xl max-h-[85vh] grid-cols-1 overflow-y-auto rounded-3xl border border-border bg-background shadow-2xl sm:grid-cols-2"
          >
            <button
              type="button"
              onClick={() => setActive(null)}
              aria-label="Close"
              className="absolute right-4 top-4 z-10 rounded-full border border-border bg-background/80 p-2 text-muted-foreground transition-colors hover:text-foreground"
            >
              <X className="h-4 w-4" />
            </button>

            <div className="flex items-center justify-center p-8 sm:p-10">
              {active.imageUrl ? (
                <div className="relative aspect-[3/4] w-full max-w-[280px]">
                  <Image
                    src={active.imageUrl}
                    alt={active.title}
                    fill
                    sizes="(max-width: 640px) 60vw, 280px"
                    className="object-contain drop-shadow-2xl"
                  />
                </div>
              ) : (
                <div className="grid aspect-[3/4] w-full max-w-[280px] place-items-center rounded-3xl bg-muted p-6">
                  <span className="font-display font-bold text-muted-foreground">{active.title}</span>
                </div>
              )}
            </div>

            <div className="flex flex-col p-8 pt-4 sm:border-l sm:border-border sm:p-10 sm:pl-8">
              {active.tagline || active.author ? (
                <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-accent-strong">
                  {variant === "read" ? active.author : active.tagline}
                </p>
              ) : (
                <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-accent-strong">
                  {variant === "ebook" ? (active.free ? "Free eBook" : "Premium eBook") : "Book"}
                </p>
              )}
              <h2 className="mt-2 font-display text-2xl font-bold leading-snug">{active.title}</h2>

              <div className="mt-4 space-y-3 text-sm leading-relaxed text-muted-foreground">
                {variant === "read" && active.learning && <p>{active.learning}</p>}
                {(variant === "published" || variant === "ebook") && active.description && (
                  <p>{active.description}</p>
                )}
                {variant === "read" && active.note && (
                  <p className="border-t border-border pt-3 text-xs text-muted-foreground/70">{active.note}</p>
                )}
              </div>

              {isFreeEbook(active) ? (
                <div className="mt-auto pt-8">
                  <button
                    type="button"
                    onClick={() => openDownload(active)}
                    className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-accent px-6 py-3 text-sm font-semibold text-accent-foreground shadow-sm transition-opacity hover:opacity-90"
                  >
                    <Download className="h-4 w-4" />
                    Download eBook
                  </button>
                </div>
              ) : variant !== "read" && active.buyUrl ? (
                <a
                  href={active.buyUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="mt-auto inline-flex items-center justify-center gap-2 pt-8"
                  onClick={() => setActive(null)}
                >
                  <span className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-accent px-6 py-3 text-sm font-semibold text-accent-foreground shadow-sm transition-opacity hover:opacity-90">
                    <ShoppingBag className="h-4 w-4" />
                    Buy Now
                  </span>
                </a>
              ) : null}
            </div>
          </div>
        </div>
      )}

      {/* Download gate modal */}
      {target && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={resetForm} />
          <div
            role="dialog"
            aria-modal="true"
            aria-label="Download eBook"
            className="relative w-full max-w-md overflow-hidden rounded-3xl border border-border bg-background shadow-2xl"
          >
            <div className="relative flex flex-col items-center bg-foreground px-8 pb-8 pt-10 text-center text-background">
              <div className="pointer-events-none absolute inset-x-0 -top-16 h-40 rounded-full bg-accent/20 blur-3xl" aria-hidden="true" />
              <button
                type="button"
                onClick={resetForm}
                aria-label="Close"
                className="absolute right-4 top-4 rounded-full border border-white/20 bg-white/10 p-2 text-white transition-colors hover:bg-white/20"
              >
                <X className="h-4 w-4" />
              </button>
              <span className="inline-flex h-12 w-12 items-center justify-center rounded-xl bg-accent text-accent-foreground">
                <Download className="h-5 w-5" />
              </span>
              <p className="mt-4 text-[10px] font-semibold uppercase tracking-[0.2em] text-accent">Free eBook</p>
              <h2 className="mt-2 font-display text-2xl font-bold leading-snug">Get your copy</h2>
              <p className="mt-2 max-w-xs text-sm leading-relaxed text-background/70">{target.title}</p>
            </div>

            <form onSubmit={submitDownload} className="space-y-4 px-8 py-7" noValidate>
              <div>
                <label htmlFor="ebook-name" className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Name
                </label>
                <input
                  id="ebook-name"
                  type="text"
                  autoComplete="name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Your name"
                  className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm outline-none transition-colors focus:border-accent"
                />
              </div>

              <div>
                <label htmlFor="ebook-email" className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Email
                </label>
                <input
                  id="ebook-email"
                  type="email"
                  autoComplete="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  className="w-full rounded-xl border border-border bg-background px-4 py-2.5 text-sm outline-none transition-colors focus:border-accent"
                />
              </div>

              <label className="flex items-start gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={acceptedTerms}
                  onChange={(e) => setAcceptedTerms(e.target.checked)}
                  className="mt-0.5 h-4 w-4 shrink-0 accent-[var(--accent)]"
                />
                <span className="text-xs leading-relaxed text-muted-foreground">
                  I have read and agree to the{" "}
                  <a href="/privacy" target="_blank" rel="noopener noreferrer" className="underline underline-offset-2 hover:text-foreground">
                    Privacy Policy
                  </a>{" "}
                  and{" "}
                  <a href="/terms" target="_blank" rel="noopener noreferrer" className="underline underline-offset-2 hover:text-foreground">
                    Terms &amp; Conditions
                  </a>
                  .
                </span>
              </label>

              <label className="flex items-start gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={optInNewsletter}
                  onChange={(e) => setOptInNewsletter(e.target.checked)}
                  className="mt-0.5 h-4 w-4 shrink-0 accent-[var(--accent)]"
                />
                <span className="text-xs leading-relaxed text-muted-foreground">
                  Yes, keep me updated with the newsletter.
                </span>
              </label>

              {error && (
                <p role="alert" className="text-sm text-red-600">
                  {error}
                </p>
              )}

              <button
                type="submit"
                disabled={submitting || !acceptedTerms}
                className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-accent px-6 py-3 text-sm font-semibold text-accent-foreground shadow-sm transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
                {submitting ? "Downloading…" : "Download eBook"}
              </button>
            </form>
          </div>
        </div>
      )}
    </>
  );
}